namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0
        ? Math.Round(Ratings.Average(), 1)
        : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1,
            Title = "Classic Margherita Pizza",
            Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes over the dough.\n4. Tear mozzarella and distribute evenly.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil."
        },
        new()
        {
            Id = 2,
            Title = "Chicken Tikka Masala",
            Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nCanned tomatoes\nHeavy cream\nGarlic\nGinger\nOnion",
            Steps = "1. Marinate chicken in yogurt and spices for 1 hour.\n2. Grill or pan-fry chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomatoes and simmer 15 minutes.\n5. Stir in cream and spices.\n6. Add chicken and simmer 10 minutes.\n7. Serve with basmati rice or naan."
        },
        new()
        {
            Id = 3,
            Title = "Spaghetti Carbonara",
            Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale (or pancetta)\nEggs\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk eggs with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, add egg mixture, toss quickly.\n6. Serve immediately with extra Pecorino."
        },
        new()
        {
            Id = 4,
            Title = "Beef Tacos",
            Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef, lettuce, tomato, cheese.\n5. Top with sour cream and salsa."
        },
        new()
        {
            Id = 5,
            Title = "Pad Thai",
            Category = "Thai",
            Ingredients = "Rice noodles\nShrimp or tofu\nEggs\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar",
            Steps = "1. Soak rice noodles in warm water 30 minutes.\n2. Mix fish sauce, tamarind paste, and sugar for sauce.\n3. Stir-fry shrimp or tofu until cooked, set aside.\n4. Scramble eggs in the wok.\n5. Add drained noodles and sauce, toss.\n6. Add protein, bean sprouts, and green onions.\n7. Serve with peanuts and lime wedges."
        },
        new()
        {
            Id = 6,
            Title = "Guacamole",
            Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nRed onion\nCilantro\nJalapeño\nTomato\nSalt",
            Steps = "1. Halve avocados, remove pit, scoop into bowl.\n2. Mash to desired consistency.\n3. Stir in diced onion, tomato, jalapeño, and cilantro.\n4. Add lime juice and salt to taste.\n5. Serve with tortilla chips."
        }
    ];

    private int _nextId = 7;

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

